import {getClient} from './supabase-client.js';import {rows,invoke,runtimeError} from './services/runtime-service.js';
export async function runtimeOverview(){return rows((await getClient()).rpc('runtime_admin',{operation:'overview'}));}
export function runtimeAdminHTML(page,value,{esc,table}){const v=value?.runtime||value;if(!v?.system)return '';const s=v.system;
const health='<button class="btn" id="check-integrations">API bağlantılarını yoxla</button><div id="integration-results" role="status" class="muted">Bağlantı yoxlanmayıb. Açarlar yalnız server secret anbarındadır.</div>';
if(page==='dashboard')return `<section class="card" style="margin-top:20px"><h2>Bu ayın AI istifadəsi</h2>${table(['Sorğu cəhdi','Giriş tokeni','Çıxış tokeni','Təxmini USD','Qeyri-müəyyən xərc'],[[Number(v.usage.requests),Number(v.usage.input_tokens),Number(v.usage.output_tokens),Number(v.usage.estimated_usd).toFixed(6),Number(v.usage.uncertain)]])}${table(['Provayder','Sorğu','Təxmini USD'],(v.by_provider||[]).map(p=>[esc(p.provider),Number(p.requests),Number(p.estimated_usd).toFixed(6)]))}<p class="format-help">Qiymətlər admin konfiqurasiyası və provider usage metadatasına əsaslanır. Provider billing invoice-u deyil. Naməlum nəticəli sorğularda konservativ rezerv saxlanır.</p><p>Push: ${Number(v.notifications.sent)} göndərilib · ${Number(v.notifications.pending)} növbədə · ${Number(v.notifications.failed)} xəta · ${Number(v.notifications.sending||0)} göndərişin nəticəsi gözlənilir.</p>${health}<h3 style="margin-top:24px">Sistem xəta kodları</h3>${table(['Komponent','Kod','Vaxt'],v.errors.map(e=>[esc(e.component),esc(e.code),esc(e.created_at)]))}</section>`;
if(page==='models')return `<div class="stack"><section class="card">${health}</section>${v.providers.map(p=>`<section class="card"><h2>${esc(p.provider)}</h2><form class="form runtime-provider" data-provider="${p.provider}"><label class="row"><input type="checkbox" name="enabled" ${p.enabled?'checked':''}>Aktiv et</label><label>Model ID<input name="model" value="${esc(p.model)}" maxlength="160" placeholder="Rəsmi model ID-si" required></label><label>Rəsmi API endpoint<input type="url" name="endpoint" value="${esc(p.endpoint)}" placeholder="Boş saxlanarsa adapterin rəsmi endpoint-i"></label><div class="budget-grid"><label>1M giriş tokeni üçün USD<input type="number" name="input_per_million" step="0.000001" min="0" value="${p.input_per_million??''}" required></label><label>1M çıxış tokeni üçün USD<input type="number" name="output_per_million" step="0.000001" min="0" value="${p.output_per_million??''}" required></label><label>Context token limiti<input type="number" name="context_tokens" min="1" max="2000000" value="${p.context_tokens||''}" required></label><label>Maksimum çıxış tokeni<input type="number" name="max_output_tokens" min="1" max="32000" value="${p.max_output_tokens||''}" required></label></div><label>İmkanlar (vergüllə: short, analysis, study)<input name="capabilities" value="${esc(p.capabilities.join(','))}"></label><p class="format-help">Model ID-si, context və token qiymətlərini provider-in aktual rəsmi sənədlərindən yoxla. Burada API açarı daxil etmə.</p><button class="btn primary">Konfiqurasiyanı saxla</button></form></section>`).join('')}</div>`;
if(page==='settings')return `<section class="card" style="margin-top:20px"><h2>AI və avtomatlaşdırma nəzarəti</h2><form id="runtime-system" class="form"><label class="row"><input name="ai_enabled" type="checkbox" ${s.ai_enabled?'checked':''}>AI sorğularını aktiv et</label><label class="row"><input name="automation_enabled" type="checkbox" ${s.automation_enabled?'checked':''}>Server AutoPilot işlərini aktiv et</label><label>Default seçim<select name="default_provider">${['auto','Gemini','Claude','Grok'].map(p=>`<option ${p===s.default_provider?'selected':''}>${p}</option>`).join('')}</select></label><label>Ümumi günlük USD limiti<input name="global_daily_usd" type="number" min="0" max="10000" step="0.001" value="${Number(s.global_daily_usd)}" required></label><label>Ümumi aylıq USD limiti<input name="global_monthly_usd" type="number" min="0" max="100000" step="0.001" value="${Number(s.global_monthly_usd)}" required></label><label>Maksimum provider cəhdi<input name="max_attempts" type="number" min="1" max="3" value="${s.max_attempts}" required></label><button class="btn primary">Saxla</button></form><p class="format-help">Default bütün maliyyə limitləri 0-dır və AI deaktivdir. Cron ayrıca konfiqurasiya olunur. Sistemi dayandırmaq üçün AutoPilot-u söndür.</p></section>`;
if(page==='movies')return `<section class="card"><h2>Günün filmi · TMDB</h2><form id="runtime-movie" class="form"><label>TMDB film ID-si (avtomatik seçim üçün boş)<input type="number" name="featured_tmdb_id" min="1" value="${s.featured_tmdb_id||''}"></label><label class="row"><input type="checkbox" name="movie_automatic" ${s.movie_automatic?'checked':''}>Avtomatik günlük seçim</label><button class="btn primary">Saxla</button></form>${health}</section>`;
if(page==='jarvis')return `<section class="card" style="margin-top:20px"><h2>İcra xətaları və cəhdlər</h2>${table(['İş ID','Status','Cəhd','Xəta'],v.job_errors.map(j=>[esc(j.id),esc(j.status),Number(j.attempts),esc(j.last_error)]))}<p class="format-help">Qeyd məzmunu bu paneldə göstərilmir. İcra limitləri və sistem dayandırması Parametrlər bölməsindədir.</p></section>`;return '';}
export function bindRuntimeAdmin(value,{toast,refresh}){const c=()=>getClient();const root=document.querySelector('#content');async function run(operation,args){try{await rows((await c()).rpc('runtime_admin',{operation,args}));toast('Konfiqurasiya saxlanıldı.');await refresh();}catch(e){toast(runtimeError(e));}}
root.querySelector('#check-integrations')?.addEventListener('click',async e=>{e.target.disabled=true;const out=root.querySelector('#integration-results');try{out.textContent='Yoxlanılır…';const {statuses}=await invoke('integration-status');out.textContent=statuses.map(s=>`${s.provider}: ${{available:'metadata endpoint-i əlçatandır',not_configured:'açar əlavə edilməyib',error:'API xəta qaytardı',unreachable:'əlçatan deyil'}[s.state]}`).join(' · ');}catch(error){out.textContent=runtimeError(error);}finally{e.target.disabled=false;}});
root.querySelectorAll('.runtime-provider').forEach(f=>f.onsubmit=e=>{e.preventDefault();const d=new FormData(f),args=Object.fromEntries(d);args.provider=f.dataset.provider;args.enabled=d.has('enabled');for(const k of ['input_per_million','output_per_million','context_tokens','max_output_tokens'])args[k]=Number(d.get(k));args.capabilities=String(d.get('capabilities')).split(',').map(x=>x.trim()).filter(x=>['short','analysis','study'].includes(x));run('provider',args);});
root.querySelector('#runtime-system')?.addEventListener('submit',e=>{e.preventDefault();const d=new FormData(e.target);run('system',{ai_enabled:d.has('ai_enabled'),automation_enabled:d.has('automation_enabled'),default_provider:d.get('default_provider'),global_daily_usd:Number(d.get('global_daily_usd')),global_monthly_usd:Number(d.get('global_monthly_usd')),max_attempts:Number(d.get('max_attempts'))});});root.querySelector('#runtime-movie')?.addEventListener('submit',e=>{e.preventDefault();const d=new FormData(e.target);run('movie',{featured_tmdb_id:d.get('featured_tmdb_id')?Number(d.get('featured_tmdb_id')):null,movie_automatic:d.has('movie_automatic')});});}
